# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">FİLM ŞERİDİ (STORYBOARD) YAZMA SÜRECİNİ DEĞERLENDİRME ÖLÇÜTLERİ (TDE4.4)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. İÇERİK, GÖRSEL VE DİL ÖLÇÜTLERİ</text>\n  <text x="34" y="88" font-size="10.6" fill="#1e3a8a">• <tspan font-weight="bold">Olay Akışı ve Yapı:</tspan> Serim, düğüm ve çözüm</text>\n  <text x="44" y="104" font-size="10.3" fill="#1e3a8a">sahnelerinin ardışık karelerde tutarlı sıralanması.</text>\n  <text x="34" y="126" font-size="10.6" fill="#1e3a8a">• <tspan font-weight="bold">Görsel-İşitsel Uyum:</tspan> Sahne çizimi, çekim ölçeği</text>\n  <text x="44" y="142" font-size="10.3" fill="#1e3a8a">(genel/yakın plan) ve ses/müzik efektlerinin uyumu.</text>\n  <text x="34" y="164" font-size="10.6" fill="#1e3a8a">• <tspan font-weight="bold">Dil ve Anlatım:</tspan> Kahramana uygun diyaloglar,</text>\n  <text x="44" y="180" font-size="10.3" fill="#1e3a8a">bağdaşıklık-bağlaşıklık ve zengin söz varlığı.</text>\n  <text x="34" y="202" font-size="10.6" fill="#1e3a8a">• <tspan font-weight="bold">İmla:</tspan> Yay ayraç ( ) ve konuşma çizgisi (—) kullanımı.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. ÖZ DEĞERLENDİRME VE PAYDAŞ TEPKİSİ</text>\n  <text x="370" y="88" font-size="10.6" fill="#14532d">• <tspan font-weight="bold">TDE4.4.1. Kendini Değerlendirme:</tspan></text>\n  <text x="380" y="104" font-size="10.3" fill="#14532d">Yazma sürecindeki duygu, düşünce, planlama ve</text>\n  <text x="380" y="120" font-size="10.3" fill="#14532d">karşılaşılan güçlükleri öz değerlendirme ile analiz etme.</text>\n  <text x="370" y="142" font-size="10.6" fill="#14532d">• <tspan font-weight="bold">Paydaş Görüşleri (Akran ve Öğretmen):</tspan></text>\n  <text x="380" y="158" font-size="10.3" fill="#14532d">Dereceli puanlama anahtarıyla alınan geri bildirimler.</text>\n  <text x="370" y="180" font-size="10.6" font-weight="bold" fill="#15803d">• TDE4.4.2. Yeni Hedef ve Paylaşım:</text>\n  <text x="380" y="196" font-size="10.3" fill="#14532d">Özgün yazar kimliği oluşturma ve eseri paylaşma.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Değerlendirme aşaması, taslak metni yetkin bir esere dönüştüren ve yazar kimliğini geliştiren üstbilişsel süreçtir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ŞİİR DİNLETİSİ VE MASAL ANLATIMI PERFORMANS DEĞERLENDİRME ÖLÇÜTLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">SES VE SÖYLEYİŞ (DİKSİYON) ÖLÇÜTLERİ</text>\n  <text x="34" y="88" font-size="10.6" fill="#713f12">• <tspan font-weight="bold">Boğumlama ve Telaffuz:</tspan> Sesleri ve heceleri</text>\n  <text x="44" y="104" font-size="10.3" fill="#713f12">yutmadan standart Türkçeyle doğru seslendirme.</text>\n  <text x="34" y="126" font-size="10.6" fill="#713f12">• <tspan font-weight="bold">Tonlama:</tspan> Korku, sevinç, coşku ve hüzün gibi</text>\n  <text x="44" y="142" font-size="10.3" fill="#713f12">duyguları sesin perde ve tınısıyla yansıtma.</text>\n  <text x="34" y="164" font-size="10.6" fill="#713f12">• <tspan font-weight="bold">Vurgu ve Durak:</tspan> Anlamca odak kelimeleri</text>\n  <text x="44" y="180" font-size="10.3" fill="#713f12">vurgulama; ölçü ve anlam yerlerinde duraklama.</text>\n  <text x="34" y="202" font-size="10.6" fill="#713f12">• <tspan font-weight="bold">İşitsel Ögeler:</tspan> Fon müziği ile sesin dengesi.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">BEDEN DİLİ VE SUNUM ÖLÇÜTLERİ</text>\n  <text x="370" y="88" font-size="10.6" fill="#581c87">• <tspan font-weight="bold">Jest ve Mimik Uyumu:</tspan> El-kol hareketleri (jest)</text>\n  <text x="380" y="104" font-size="10.3" fill="#581c87">ile yüz ifadelerinin (mimik) abartısız ve doğal kullanımı.</text>\n  <text x="370" y="126" font-size="10.6" fill="#581c87">• <tspan font-weight="bold">Göz Teması ve Duruş:</tspan> Dinleyicilerin tamamını</text>\n  <text x="380" y="142" font-size="10.3" fill="#581c87">kuşatan göz teması ve öz güvenli sahne duruşu.</text>\n  <text x="370" y="164" font-size="10.6" fill="#581c87">• <tspan font-weight="bold">Akıcılık:</tspan> «uh, ıı, şey» gibi gereksiz seslerden</text>\n  <text x="380" y="180" font-size="10.3" fill="#581c87">kaçınarak akıcı ve canlı bir anlatım sürdürme.</text>\n  <text x="370" y="202" font-size="10.6" fill="#581c87">• <tspan font-weight="bold">Zaman ve Mekân Yönetimi:</tspan> Süreye uyum.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Sözün ezgisi; doğru telaffuz, duyguya uygun vurgu-tonlama ve etkili beden diliyle dinleyiciye ulaşır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">1. TEMA (\'SÖZÜN EZGİSİ\') BÜTÜNCÜL KAVRAM VE TÜR HARİTASI</text>\n  <rect x="18" y="42" width="214" height="172" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="62" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. SÖZLÜ VE EZGİLİ TÜRLER</text>\n  <text x="28" y="84" font-size="10.2" fill="#1e3a8a">• <tspan font-weight="bold">Ninni:</tspan> Anonim halk şiiri;</text>\n  <text x="34" y="98" font-size="10" fill="#1e3a8a">çocuk uyutma ezgisi (dandini...).</text>\n  <text x="28" y="118" font-size="10.2" fill="#1e3a8a">• <tspan font-weight="bold">Koşuk:</tspan> İslamiyet öncesi; kopuz,</text>\n  <text x="34" y="132" font-size="10" fill="#1e3a8a">dörtlük, hece, doğa ve yiğitlik.</text>\n  <text x="28" y="152" font-size="10.2" fill="#1e3a8a">• <tspan font-weight="bold">Türkü:</tspan> Halk şiiri; bağlama,</text>\n  <text x="34" y="166" font-size="10" fill="#1e3a8a">asıl sözler (bent) + kavuştak.</text>\n  <text x="28" y="186" font-size="10.2" fill="#1e3a8a">• <tspan font-weight="bold">Masal:</tspan> Döşeme, olay, dilek;</text>\n  <text x="34" y="200" font-size="10" fill="#1e3a8a">tekerleme ve olağanüstülük.</text>\n  <rect x="243" y="42" width="214" height="172" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="62" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">2. AHENK VE SÖZ SANATLARI</text>\n  <text x="253" y="84" font-size="10.2" fill="#14532d">• <tspan font-weight="bold">Ölçü ve Durak:</tspan> 7\'li, 8\'li, 11\'li</text>\n  <text x="259" y="98" font-size="10" fill="#14532d">hece ölçüsü ve nefes durakları.</text>\n  <text x="253" y="118" font-size="10.2" fill="#14532d">• <tspan font-weight="bold">Kafiye ve Redif:</tspan> Yarım, tam,</text>\n  <text x="259" y="132" font-size="10" fill="#14532d">zengin, tunç, cinaslı uyak.</text>\n  <text x="253" y="152" font-size="10.2" fill="#14532d">• <tspan font-weight="bold">Ses Tekrarları:</tspan> Aliterasyon</text>\n  <text x="259" y="166" font-size="10" fill="#14532d">(ünsüz) ve Asonans (ünlü).</text>\n  <text x="253" y="186" font-size="10.2" fill="#14532d">• <tspan font-weight="bold">Edebî Sanatlar:</tspan> Teşbih, istiare,</text>\n  <text x="259" y="200" font-size="10" fill="#14532d">teşhis, intak, tezat, mübalağa.</text>\n  <rect x="468" y="42" width="214" height="172" rx="8" fill="#ffedd5" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="575" y="62" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">3. EDEBİYAT ATÖLYESİ</text>\n  <text x="478" y="84" font-size="10.2" fill="#7c2d12">• <tspan font-weight="bold">Şiir Dinletisi:</tspan> Tematik şiir</text>\n  <text x="484" y="98" font-size="10" fill="#7c2d12">seçimi, vurgu, tonlama, beden dili.</text>\n  <text x="478" y="118" font-size="10.2" fill="#7c2d12">• <tspan font-weight="bold">Film Şeridi (Storyboard):</tspan></text>\n  <text x="484" y="132" font-size="10" fill="#7c2d12">Masalı görsel karelere, sahne</text>\n  <text x="484" y="146" font-size="10" fill="#7c2d12">yönergelerine ve diyaloğa dökme.</text>\n  <text x="478" y="166" font-size="10.2" fill="#7c2d12">• <tspan font-weight="bold">Süreç Değerlendirme:</tspan> Öz ve</text>\n  <text x="484" y="180" font-size="10" fill="#7c2d12">akran değerlendirme, KWL</text>\n  <text x="484" y="194" font-size="10" fill="#7c2d12">(Ne Biliyorum-İstiyorum-Öğrendim).</text>\n  <rect x="18" y="222" width="664" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="239" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">1. Tema tamamlanırken 2. Tema olan \'Kelimelerin Ritmi\'nde Klasik Türk Şiiri (gazel, kaside) ve Saf Şiir incelenecektir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
